import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { toast } from 'react-toastify';
import { User, Mail, Lock, Eye, EyeOff, Facebook, Twitter } from 'lucide-react';

const Register = () => {
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (formData.password !== formData.confirmPassword) {
      toast.error('Passwords do not match');
      return;
    }

    if (formData.password.length < 6) {
      toast.error('Password must be at least 6 characters');
      return;
    }

    setLoading(true);

    const result = await register(formData.username, formData.email, formData.password);
    
    if (result.success) {
      toast.success('Registration successful!');
    } else {
      toast.error(result.error);
    }
    
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gray-100 flex">
      {/* Left Side - Illustration */}
      <div className="hidden lg:flex lg:w-1/2 bg-white items-center justify-center p-12">
        <div className="max-w-md">
          {/* Office Workspace Illustration */}
          <div className="relative">
            {/* Wall with shelves */}
            <div className="absolute top-0 left-0 w-full h-32">
              {/* Top shelf */}
              <div className="absolute top-4 left-8 w-32 h-2 bg-gray-300 rounded"></div>
              <div className="absolute top-2 left-10 w-6 h-6 bg-gray-400 rounded"></div>
              <div className="absolute top-2 left-18 w-6 h-6 bg-gray-400 rounded"></div>
              <div className="absolute top-2 left-26 w-4 h-4 bg-green-400 rounded-full"></div>
              
              {/* Bottom shelf */}
              <div className="absolute top-12 left-8 w-32 h-2 bg-gray-300 rounded"></div>
              <div className="absolute top-10 left-10 w-4 h-4 bg-blue-400 rounded"></div>
              <div className="absolute top-10 left-16 w-4 h-4 bg-blue-400 rounded"></div>
              <div className="absolute top-10 left-22 w-4 h-4 bg-blue-400 rounded"></div>
              <div className="absolute top-10 left-28 w-4 h-4 bg-yellow-400 rounded"></div>
            </div>
            
            {/* Desk */}
            <div className="mt-32">
              <div className="w-80 h-32 bg-gray-200 rounded-lg relative">
                {/* Desk base */}
                <div className="absolute bottom-0 left-4 w-72 h-8 bg-gray-300 rounded"></div>
                
                {/* Plant on left */}
                <div className="absolute top-4 left-4 w-6 h-8 bg-purple-600 rounded-full"></div>
                <div className="absolute top-2 left-5 w-4 h-4 bg-green-400 rounded-full"></div>
                
                {/* Computer monitor */}
                <div className="absolute top-6 left-12 w-16 h-12 bg-gray-800 rounded">
                  <div className="absolute top-1 left-1 w-14 h-10 bg-white rounded-sm">
                    <div className="absolute top-1 left-1 w-12 h-1 bg-blue-500 rounded"></div>
                    <div className="absolute top-3 left-1 w-1 h-1 bg-gray-400 rounded-full"></div>
                    <div className="absolute top-3 left-3 w-1 h-1 bg-gray-400 rounded-full"></div>
                    <div className="absolute top-3 left-5 w-1 h-1 bg-gray-400 rounded-full"></div>
                    <div className="absolute top-3 left-7 w-1 h-1 bg-gray-400 rounded-full"></div>
                    <div className="absolute top-5 left-1 w-8 h-1 bg-gray-300 rounded"></div>
                    <div className="absolute top-6 left-1 w-6 h-1 bg-gray-300 rounded"></div>
                  </div>
                </div>
                
                {/* Tablet/Clipboard */}
                <div className="absolute top-8 left-32 w-8 h-10 bg-white rounded border-2 border-gray-300">
                  <div className="absolute top-1 left-1 w-6 h-1 bg-gray-400 rounded"></div>
                  <div className="absolute top-2 left-1 w-6 h-1 bg-gray-400 rounded"></div>
                  <div className="absolute top-3 left-1 w-6 h-1 bg-gray-400 rounded"></div>
                  <div className="absolute top-4 left-1 w-2 h-1 bg-gray-400 rounded"></div>
                  <div className="absolute top-4 left-4 w-2 h-1 bg-gray-400 rounded"></div>
                </div>
                
                {/* Filing cabinet */}
                <div className="absolute top-12 left-44 w-8 h-16 bg-gray-400 rounded">
                  <div className="absolute top-2 left-1 w-6 h-2 bg-gray-500 rounded"></div>
                  <div className="absolute top-5 left-1 w-6 h-2 bg-gray-500 rounded"></div>
                  <div className="absolute top-8 left-1 w-6 h-2 bg-gray-500 rounded"></div>
                  <div className="absolute top-11 left-1 w-6 h-2 bg-gray-500 rounded"></div>
                </div>
                
                {/* Person */}
                <div className="absolute -top-8 left-16">
                  {/* Chair */}
                  <div className="w-6 h-8 bg-purple-600 rounded"></div>
                  {/* Person */}
                  <div className="absolute -top-4 left-2 w-4 h-4 bg-gray-300 rounded-full"></div>
                  <div className="absolute -top-2 left-1 w-6 h-6 bg-blue-800 rounded"></div>
                  <div className="absolute top-2 left-1 w-6 h-4 bg-gray-600 rounded"></div>
                </div>
                
                {/* Plant on right */}
                <div className="absolute top-4 right-4 w-8 h-12 bg-gray-400 rounded">
                  <div className="absolute top-0 left-1 w-6 h-6 bg-purple-500 rounded-full"></div>
                  <div className="absolute top-2 left-0 w-6 h-6 bg-purple-500 rounded-full"></div>
                  <div className="absolute top-4 left-2 w-6 h-6 bg-purple-500 rounded-full"></div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Right Side - Register Form */}
      <div className="w-full lg:w-1/2 flex items-center justify-center p-12">
        <div className="w-full max-w-md">
          <div className="text-center mb-8">
            <h2 className="text-4xl font-bold text-gray-800 mb-4">Sign Up</h2>
            <p className="text-gray-600 text-lg">
              Lorem ipsum dolor sit amet elit. Sapiente sit aut eos consectetur adipisicing.
            </p>
          </div>

          <form className="space-y-6" onSubmit={handleSubmit}>
            <div>
              <input
                id="username"
                name="username"
                type="text"
                required
                className="w-full px-4 py-4 border border-gray-300 rounded-lg text-lg focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                placeholder="Username"
                value={formData.username}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <input
                id="email"
                name="email"
                type="email"
                required
                className="w-full px-4 py-4 border border-gray-300 rounded-lg text-lg focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                placeholder="Email"
                value={formData.email}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <input
                id="password"
                name="password"
                type={showPassword ? 'text' : 'password'}
                required
                className="w-full px-4 py-4 border border-gray-300 rounded-lg text-lg focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                placeholder="Password"
                value={formData.password}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <input
                id="confirmPassword"
                name="confirmPassword"
                type={showConfirmPassword ? 'text' : 'password'}
                required
                className="w-full px-4 py-4 border border-gray-300 rounded-lg text-lg focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                placeholder="Confirm Password"
                value={formData.confirmPassword}
                onChange={handleChange}
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-purple-600 text-white py-4 px-6 rounded-lg text-lg font-semibold hover:bg-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-2 transition-colors disabled:opacity-50"
            >
              {loading ? 'Creating account...' : 'Sign Up'}
            </button>

            <div className="relative my-6">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-300"></div>
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-2 bg-white text-gray-500">– or sign up with –</span>
              </div>
            </div>

            <div className="flex justify-center space-x-4">
              <button
                type="button"
                className="w-12 h-12 bg-blue-600 rounded-full flex items-center justify-center text-white hover:bg-blue-700 transition-colors"
              >
                <Facebook className="w-6 h-6" />
              </button>
              <button
                type="button"
                className="w-12 h-12 bg-sky-500 rounded-full flex items-center justify-center text-white hover:bg-sky-600 transition-colors"
              >
                <Twitter className="w-6 h-6" />
              </button>
              <button
                type="button"
                className="w-12 h-12 bg-red-600 rounded-full flex items-center justify-center text-white hover:bg-red-700 transition-colors"
              >
                <span className="text-lg font-bold">G</span>
              </button>
            </div>

            <div className="text-center">
              <p className="text-gray-600">
                Already have an account?{' '}
                <Link
                  to="/login"
                  className="text-purple-600 hover:text-purple-500 font-medium"
                >
                  Sign in here
                </Link>
              </p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Register;
